import EventEmitter from 'eventemitter3';
import { IOpenSubMenuOptions, ISubSettingMenu, SubMenuEvents } from './types';

class SubMenuItemManager extends EventEmitter<SubMenuEvents> {
    private subMenus: Map<string, ISubSettingMenu>;
    private activeSubMenus: ISubSettingMenu[] = [];

    constructor() {
        super();
        this.subMenus = new Map();
        this.activeSubMenus = [];
    }

    public add(subMenu: ISubSettingMenu) {
        this.subMenus.set(subMenu.id, subMenu);
    }

    public close() {
        this.activeSubMenus.pop();
        if (this.activeSubMenus.length === 0) {
            this.emit('close');
        } else {
            const lastMenu = this.activeSubMenus[this.activeSubMenus.length-1];
            this.emit('open', { id: lastMenu.id, label: lastMenu.label, props: lastMenu.props });
        }
    }

    public open(options: IOpenSubMenuOptions) {
        const match = this.get(options.id);
        match.props = options.props ?? match.props ?? {};
        match.label = options.label ?? match.label;
        if (!options.nested) {
            this.close();
        }
        this.activeSubMenus.push(match);
        this.emit('open', options);
    }

    public get(id: string) {
        const match = this.subMenus.get(id);

        if (!match) {
            throw new Error(`Could not find sub menu item with id "${id}"`);
        }

        return match;
    }

    public remove(id: string) {
        this.subMenus.delete(id);
    }
}

export const SubMenuManager = new SubMenuItemManager();